import test from "node:test";
import assert from "node:assert/strict";

// CodeQL js/polynomial-redos #1325, #1324, #1296: three model/library id regexes backtracked in
// O(n^2) on crafted ids. Each id reaches its regex without a length cap (a client model id
// "gh/<id>", an upstream /v1/models id, a raw Context7 search item id).
//
// Two checks per function:
// - a 50k-char pathological id returns fast (measured on the exported function);
// - a truth table generated by running the pre-fix functions (git show of the base) stays the
//   same, so the linear rewrites keep the exact accept/reject behavior.

const { inferGithubUnsyncedTargetFormat } =
  await import("../../src/sse/services/githubResponsesFallback.ts");
const { modelDisplayName } = await import("../../src/shared/utils/modelDisplayName.ts");
const { isValidContext7LibraryId } = await import("../../open-sse/executors/context7-fetch.ts");

const PATHOLOGICAL_LENGTH = 50_000;
const BUDGET_MS = 200;

function elapsedMs(fn: () => unknown): number {
  const start = performance.now();
  fn();
  return performance.now() - start;
}

