test("#1325 GitHub Responses-only inference is linear on a 'codex' run ending in a line break", () => {
  const id = "codex".repeat(PATHOLOGICAL_LENGTH / 5) + "\n!";
  let result: unknown = "unset";
  const ms = elapsedMs(() => {
    result = inferGithubUnsyncedTargetFormat("gh", id);
  });
  assert.equal(result, undefined);
  assert.ok(ms < BUDGET_MS, `took ${ms.toFixed(1)}ms`);
});

test("#1325 GitHub Responses-only inference keeps the pre-fix truth table", () => {
  for (const [providerId, modelId, expected] of GITHUB_TABLE) {
    assert.equal(
      inferGithubUnsyncedTargetFormat(providerId, modelId) ?? null,
      expected,
      JSON.stringify([providerId, modelId])
    );
  }
});

test("#1324 model display name is linear on a long version-marker token", () => {
  const id = "gpt-v" + "0".repeat(PATHOLOGICAL_LENGTH - 6) + "x";
  let result = "";
  const ms = elapsedMs(() => {
    result = modelDisplayName(id);
  });
  assert.ok(result.startsWith("GPT V0"));
  assert.ok(ms < BUDGET_MS, `took ${ms.toFixed(1)}ms`);
});

test("#1324 model display name keeps the pre-fix truth table", () => {
  for (const [id, expected] of DISPLAY_TABLE) {
    assert.equal(modelDisplayName(id), expected, JSON.stringify(id));
  }
});

test("#1296 Context7 library id check is linear on a run of slashes ending in a line break", () => {
  for (const id of [
    "/".repeat(PATHOLOGICAL_LENGTH - 1) + "\n",
    "/a".repeat(PATHOLOGICAL_LENGTH / 2 - 1) + "\n",
  ]) {
    let result: unknown = "unset";
    const ms = elapsedMs(() => {
      result = isValidContext7LibraryId(id);
    });
    assert.equal(result, false);
    assert.ok(ms < BUDGET_MS, `took ${ms.toFixed(1)}ms`);
  }
});

test("#1296 Context7 library id check keeps the pre-fix truth table", () => {
  for (const [id, expected] of CONTEXT7_TABLE) {
    assert.equal(isValidContext7LibraryId(id), expected, JSON.stringify(id));
  }
});
